class Solution {
    public boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) continue;
            int slow = i, fast = i;
            while (nums[next(slow, nums)] * nums[i] > 0 &&
                   nums[next(fast, nums)] * nums[i] > 0 &&
                   nums[next(next(fast, nums), nums)] * nums[i] > 0) {
                slow = next(slow, nums);
                fast = next(next(fast, nums), nums);
                if (slow == fast) {
                    if (slow == next(slow, nums)) break;
                    return true;
                }
            }
            int j = i;
            while (nums[j] * nums[i] > 0) {
                int tmp = next(j, nums);
                nums[j] = 0;
                j = tmp;
            }
        }
        return false;
    }

    private int next(int i, int[] nums) {
        int n = nums.length;
        return ((i + nums[i]) % n + n) % n;
    }
}

class Solution {
    public boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        int[] color = new int[n];
        int colorId = 0;
        for (int i = 0; i < n; i++) {
            if (color[i] != 0) continue;
            colorId++;
            int j = i;
            while (color[j] == 0 && nums[j] * nums[i] > 0) {
                color[j] = colorId;
                j = ((j + nums[j]) % n + n) % n;
            }
            if (color[j] == colorId) {
                int k = j;
                int len = 0;
                do {
                    len++;
                    k = ((k + nums[k]) % n + n) % n;
                } while (k != j);
                if (len > 1) return true;
            }
        }
        return false;
    }
}
